import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

export function packContext(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) throw new Error('sections must be an array');

  const ids = new Set();
  const entries = [];
  // Validate every entry before making any budget decisions.
  for (let index = 0; index < sections.length; index++) {
    if (!Object.hasOwn(sections, index)) throw new Error('sections must be dense');
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      throw new Error('Each section must be an object');
    }
    const { id, text, priority, required } = section;
    if (typeof id !== 'string' || id.length === 0 ||
        typeof text !== 'string' ||
        !Number.isSafeInteger(priority) || priority < 0 ||
        typeof required !== 'boolean') {
      throw new Error('Invalid section fields');
    }
    if (ids.has(id)) throw new Error('Duplicate section ID');
    ids.add(id);
    entries.push({ id, text, priority, required, index });
  }

  for (const entry of entries) {
    entry.frame = '### ' + JSON.stringify(entry.id) + '\n' + entry.text + '\n';
    entry.cost = Buffer.byteLength(entry.frame, 'utf8');
  }

  const frames = [];
  const included = [];
  const selected = new Set();
  let remaining = maxBytes;
  function include(entry) {
    remaining -= entry.cost;
    frames.push(entry.frame);
    included.push(entry.id);
    selected.add(entry.id);
  }

  for (const entry of entries) {
    if (!entry.required) continue;
    if (entry.cost > remaining) throw new Error('Required sections exceed maxBytes');
    include(entry);
  }
  const optional = entries.filter(entry => !entry.required);
  optional.sort((a, b) => b.priority - a.priority || a.index - b.index);
  for (const entry of optional) {
    if (entry.cost <= remaining) include(entry);
  }

  return {
    text: frames.join(''),
    bytes: maxBytes - remaining,
    included,
    omitted: entries.filter(entry => !entry.required && !selected.has(entry.id))
      .map(entry => entry.id),
  };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    if (process.argv.length !== 3) throw new Error('Expected exactly one INPUT_JSON_FILE argument');
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    const result = packContext(input.sections, input.maxBytes);
    process.stdout.write(JSON.stringify(result) + '\n');
  } catch (error) {
    process.stderr.write(`context-packet: ${error.message}\n`);
    process.exitCode = 2;
  }
}

