import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const section = (id, text = '', priority = 0, required = false) =>
  ({ id, text, priority, required });
const frame = s => '### ' + JSON.stringify(s.id) + '\n' + s.text + '\n';
const cli = fileURLToPath(new URL('../context-packet.js', import.meta.url));
const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });

test('strict validation applies to all entries at zero budget', () => {
  for (const budget of [-1, 1.5, NaN, Infinity, '0', null, 2 ** 53]) {
    assert.throws(() => packContext([], budget), Error);
  }
  for (const sections of [null, {}, 'x', [null], [[]], [42], new Array(2)]) {
    assert.throws(() => packContext(sections, 0), Error);
  }
  for (const [field, values] of Object.entries({
    id: ['', 1, null], text: [undefined, null, 2],
    priority: [-1, 0.5, '0', Infinity, 2 ** 53], required: [0, 'false', null],
  })) {
    for (const value of values) {
      assert.throws(() => packContext([section('ok'), { ...section('bad'), [field]: value }], 0), Error);
    }
    const missing = section('missing');
    delete missing[field];
    assert.throws(() => packContext([missing], 0), Error);
  }
  assert.throws(() => packContext([section('__proto__'), section('__proto__')], 0), Error);
});

test('preserves arbitrary IDs, source text, ordering, and byte counts', () => {
  const sections = [
    section('large first', 'x'.repeat(200), 1),
    section('large second', 'x'.repeat(200), 100),
    section('__proto__', ' \r\n雪\u0000 ', 3),
    section('A', '', 0, true),
    section('a', '', 999, true),
    section(' \n\u0000😀', 'é', 3),
  ];
  sections.forEach(Object.freeze);
  Object.freeze(sections);
  const expected = [sections[3], sections[4], sections[2], sections[5]];
  const text = expected.map(frame).join('');
  const bytes = Buffer.byteLength(text, 'utf8');
  assert.deepEqual(packContext(sections, bytes), {
    text, bytes, included: expected.map(s => s.id), omitted: ['large first', 'large second'],
  });
  assert.deepEqual(packContext([], Number.MAX_SAFE_INTEGER), {
    text: '', bytes: 0, included: [], omitted: [],
  });
  assert.throws(() => packContext(expected.map(s => ({ ...s, required: true })), bytes - 1), Error);
});

test('CLI success, failures, and import without side effects', () => {
  const directory = mkdtempSync(join(tmpdir(), 'context-packet-'));
  try {
    const file = join(directory, 'input.json');
    const input = { sections: [section('雪', ' hello\n')], maxBytes: 100, extra: true };
